SELECT SUM(ORDERED_QUANTITY) / NULLIF(SUM(ORDER_COUNT), 0) AS ORDERED_QUANTITY_PER_ORDER
FROM ZOMATO_DLR.MARTS.MART_ORDER_ITEM_CITY_CURRENCY_DAY_UTC
WHERE ORDER_DATE_UTC >= '2025-01-01' AND ORDER_DATE_UTC < '2026-01-01';

SELECT SUM(ORDERED_QUANTITY) / NULLIF(COUNT(DISTINCT ORDER_ID), 0) AS ORDERED_QUANTITY_PER_ORDER
FROM ZOMATO_DLR.CORE.FACT_ORDER_ITEM
WHERE ORDER_DATE >= '2025-01-01' AND ORDER_DATE < '2026-01-01';
